create type public.real_estate_lead_type as enum ('seller','buyer','landlord','renter','investor');
create type public.real_estate_lead_stage as enum ('new','attempted_contact','contacted','qualified','appointment_scheduled','showing','offer','under_contract','closed','nurture','lost');
create table public.real_estate_leads (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, first_name text not null, last_name text not null default '', email text, phone text, lead_type public.real_estate_lead_type not null, stage public.real_estate_lead_stage not null default 'new', source text, assigned_to uuid references auth.users, notes text, tags text[] not null default '{}', preferred_communication text, communication_consent boolean not null default false, lead_score smallint not null default 0 check (lead_score between 0 and 100), lead_score_reasons jsonb not null default '[]', profile jsonb not null default '{}', last_contacted_at timestamptz, next_follow_up_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.real_estate_lead_activities (id uuid primary key default gen_random_uuid(), lead_id uuid not null references public.real_estate_leads on delete cascade, user_id uuid not null references auth.users on delete cascade, kind text not null, body text, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.real_estate_tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, lead_id uuid references public.real_estate_leads on delete cascade, title text not null, due_at timestamptz, priority text not null default 'normal', status text not null default 'open', notes text, created_at timestamptz not null default now());
create index real_estate_leads_owner_stage_idx on public.real_estate_leads(user_id, stage); create index real_estate_leads_follow_up_idx on public.real_estate_leads(user_id, next_follow_up_at);
alter table public.real_estate_leads enable row level security; alter table public.real_estate_lead_activities enable row level security; alter table public.real_estate_tasks enable row level security;
create policy "owners manage real estate leads" on public.real_estate_leads for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "owners manage lead activities" on public.real_estate_lead_activities for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "owners manage real estate tasks" on public.real_estate_tasks for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
